42	// 上一班结束时记录全部原样保留，本次失败不成为任何业务事实。
43	func assertStillOpenAfterFailedClose(t *testing.T, f *fixture, w failedCloseExpectations) {
44		t.Helper()
45	
46		// 失败尝试不新增班次或交接，也不复制事项。
47		if hs := f.svc.ListShifts(); len(hs) != 2 {
48			t.Fatalf("失败尝试不应新增班次，got %d 个：%+v", len(hs), hs)
49		}
50		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
51			t.Fatalf("失败尝试不应新增交接：%+v", hs)
52		}
53		for _, id := range []string{w.idOpen, w.idNew, w.idClosed} {
54			if n := countItems(f, id); n != 1 {
55				t.Fatalf("失败尝试不应复制事项，编号 %s 出现 %d 次", id, n)
56			}
57		}
58	
59		// 本班仍在进行中：没有结束时间，也没有结束时记录。
60		b, err := f.svc.GetShift(w.bID)
61		if err != nil {
62			t.Fatalf("get shift: %v", err)
63		}
64		if b.Closed || b.ClosedAt != nil || b.CloseRecord != nil {
65			t.Fatalf("保存失败后班次应仍在进行中、无结束时间与结束时记录：%+v", b)
66		}
67	
68		// 查看本班：事项区仍展示当前信息，不被标成结束时记录或历史不完整；
69		// 本班只含两项（本班新增已关闭项、上一班交来仍未关闭项），各一次并按
70		// 编号排列；上一班已关闭的事项不属于本班，不能被拉进本班清单。
71		repB, err := f.svc.ShiftReport(w.bID)
72		if err != nil {
73			t.Fatalf("report b: %v", err)
74		}
75		if repB.Shift.Closed || repB.ItemsAtClose || repB.HistoryIncomplete {
76			t.Fatalf("进行中班次不应出现结束时记录或历史不完整标记：%+v", repB.Shift)
77		}
78		if len(repB.CloseItems) != 0 {
