180		}
181	
182		// 展示层与保存事实一致：本班事项区是当前信息而非结束时记录，不出现失败
183		// 尝试的结束时间；上一班仍展示自己的结束时记录。
184		textB := FormatReport(repB)
185		if strings.Contains(textB, "结束时记录") || strings.Contains(textB, fmtTime(w.failAt)) {
186			t.Fatalf("本班报告不应出现结束时记录或失败尝试时刻：\n%s", textB)
187		}
188		if !strings.Contains(textB, "\n事项：\n") || !strings.Contains(textB, w.midContent) ||
189			!strings.Contains(textB, "后续负责人："+w.midFollow) {
