231		}
232		if len(jOpen.Results) != 1 || jOpen.Results[0].Entry.Status != EntryTracking ||
233			jOpen.Results[0].Entry.FollowOwner != w.trackFollow {
234			t.Fatalf("交接当前结果应保留接收时的继续跟踪记录：%+v", jOpen.Results)
235		}
236		for _, id := range []string{w.idNew, w.idClosed} {
237			j, err := f.svc.ItemJourney(id)
238			if err != nil {
239				t.Fatalf("journey %s: %v", id, err)
240			}
241			if got := joinStrings(journeyKinds(j)); got != "created,closed" {
242				t.Fatalf("已关闭事项 %s 的处理经过应保持创建与关闭，got %s", id, got)
243			}
244			for _, ev := range j.Events {
